import {evaluate,formatResult} from './calculator-engine.js?v=8';
import {sequence,fields,serialize,insert,navigate,exitStructure,unwrapEmpty} from './calculator-tree.js?v=8';
let remembered='basic';try{remembered=sessionStorage.getItem('calculator-mode')||'basic'}catch{}
let answer={value:0,exact:[0n,1n]};
export function mountCalculator(host,{language=()=> 'en',onClose=()=>{host.hidden=true}}={}){
 const tr=(a,b)=>language()==='bm'?b:a;let mode=['basic','scientific','natural'].includes(remembered)?remembered:'basic',angle='DEG',text='',tree=sequence(),active=fields(tree)[0].id,selection=[0,0],result=null,exact=false,error='';
 const el=(tag,cls='',label)=>{const n=document.createElement(tag);n.className=cls;if(label!==undefined)n.textContent=label;return n};
 const names={'+':['Add','Tambah'],'−':['Subtract','Tolak'],'×':['Multiply','Darab'],'÷':['Divide','Bahagi'],'=':['Equals','Sama dengan'],'.':['Decimal point','Titik perpuluhan'],'(':['Open parentheses','Buka kurungan'],')':['Close parentheses','Tutup kurungan'],'±':['Change sign','Tukar tanda'],'%':['Percent','Peratus'],'Ans':['Previous answer','Jawapan sebelumnya'],'C':['Clear','Kosongkan'],'DEL':['Delete','Padam'],'a/b':['Fraction','Pecahan'],'xʸ':['Power','Kuasa'],'x²':['Square','Kuasa dua'],'√':['Square root','Punca kuasa dua'],'ⁿ√':['Nth root','Punca ke-n'],'1/x':['Reciprocal','Salingan'],'π':['Pi','Pi'],'e':['Euler constant','Pemalar Euler'],'!':['Factorial','Faktorial'],'10ˣ':['Power of ten','Kuasa sepuluh'],'eˣ':['Exponential','Eksponen'],'×10ⁿ':['Scientific notation','Notasi saintifik'],'←':['Cursor left','Kursor kiri'],'→':['Cursor right','Kursor kanan'],'↑':['Cursor up','Kursor atas'],'↓':['Cursor down','Kursor bawah'],'sin':['Sine','Sinus'],'cos':['Cosine','Kosinus'],'tan':['Tangent','Tangen'],'asin':['Inverse sine','Sinus songsang'],'acos':['Inverse cosine','Kosinus songsang'],'atan':['Inverse tangent','Tangen songsang'],'log':['Base ten logarithm','Logaritma asas sepuluh'],'ln':['Natural logarithm','Logaritma asli'],'abs':['Absolute value','Nilai mutlak']};
 const label=k=>names[k]?tr(...names[k]):k;
 function btn(k,fn,visible=k){const b=el('button','',visible);b.type='button';b.title=b.ariaLabel=label(k);b.onpointerdown=e=>e.preventDefault();b.onclick=fn;return b;}
 function focus(id=active,pos){const input=host.querySelector(`[data-field="${id}"]`);if(input){active=id;input.focus();const p=pos??input.value.length;input.setSelectionRange(p,p);selection=[p,p];}}
 function output(){const t=host.querySelector('.calc-exact');t.disabled=!result?.exact;t.setAttribute('aria-pressed',String(exact));const out=host.querySelector('.calc-result');out.replaceChildren();if(error){const errors={syntax:['Check the expression.','Semak ungkapan.'],zero:['Cannot divide by zero.','Tidak boleh bahagi dengan sifar.'],domain:['Outside the function’s valid range.','Di luar julat fungsi yang sah.'],limit:['Expression is too long.','Ungkapan terlalu panjang.']};out.textContent=tr(...(errors[error]||errors.syntax));return;}if(!result){out.textContent=tr('Result','Hasil');return;}if(exact&&result.exact&&result.exact[1]!==1n&&mode==='natural'){const f=el('span','calc-fraction');f.append(el('span','',String(result.exact[0])),el('span','',String(result.exact[1])));out.append(f);}else out.textContent=formatResult(result,exact);const toggle=host.querySelector('.calc-exact');toggle.disabled=!result.exact;toggle.setAttribute('aria-pressed',String(exact));}
 function solve(){try{result=evaluate(mode==='natural'?serialize(tree):text,{angle,ans:answer});answer=result;error='';}catch(e){error=e.message;result=null;}output();}
 function treeDOM(node,path=tr('Expression','Ungkapan')){if(node.type==='Text'){const i=el('input','math-slot');i.value=node.text;i.dataset.field=node.id;i.ariaLabel=path;i.autocomplete='off';i.spellcheck=false;i.style.width=Math.max(2,node.text.length+1)+'ch';i.oninput=()=>{node.text=i.value;i.style.width=Math.max(2,i.value.length+1)+'ch';error='';};const save=()=>{active=node.id;selection=[i.selectionStart,i.selectionEnd]};i.onfocus=i.onselect=i.onclick=i.onkeyup=save;i.onkeydown=e=>{save();if(e.key==='Enter'){e.preventDefault();solve();return;}const directions={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};if(directions[e.key]&&(e.key==='ArrowUp'||e.key==='ArrowDown'||(e.key==='ArrowLeft'&&i.selectionStart===0)||(e.key==='ArrowRight'&&i.selectionStart===i.value.length))){e.preventDefault();focus(navigate(tree,active,directions[e.key]));}if((e.key==='Backspace'||e.key==='Delete')&&!i.value&&unwrapEmpty(tree,active)){e.preventDefault();active=fields(tree)[0].id;render();focus();}};return i;}
 const box=el('span','math-'+node.type.toLowerCase());if(node.type==='Sequence'){node.children.forEach(x=>box.append(treeDOM(x,path)));}else if(node.type==='Fraction'){box.append(treeDOM(node.numerator,tr('Numerator','Pengangka')),treeDOM(node.denominator,tr('Denominator','Penyebut')));}else if(node.type==='Power'){box.append(treeDOM(node.base,tr('Base','Asas')),treeDOM(node.exponent,tr('Exponent','Eksponen')));}else if(node.type==='Root'||node.type==='Sqrt'){if(node.index)box.append(treeDOM(node.index,tr('Root index','Indeks punca')));box.append(el('span','radical','√'),treeDOM(node.body,tr('Inside root','Dalam punca')));}else{box.append(el('span','',node.type==='Function'?node.name+'(':'('),treeDOM(node.body,path),el('span','',')'));}return box;}
 function add(s){if(mode==='natural'){const f=fields(tree).find(f=>f.id===active)||fields(tree)[0];f.text=f.text.slice(0,selection[0])+s+f.text.slice(selection[1]);const p=selection[0]+s.length;active=f.id;render();focus(active,p);}else{const input=host.querySelector('.calc-linear'),a=input.selectionStart??text.length,b=input.selectionEnd??a;text=text.slice(0,a)+s+text.slice(b);input.value=text;input.focus();input.setSelectionRange(a+s.length,a+s.length);}}
 function structure(type,name){active=insert(tree,active,...selection,type,name)||active;render();focus(active,0);}
 function key(k){if(k==='='){solve();return;}if(k==='C'){text='';tree=sequence();active=fields(tree)[0].id;selection=[0,0];result=null;error='';render();return;}if(k==='DEL'){if(mode==='natural'){const f=fields(tree).find(f=>f.id===active);if(!f.text&&unwrapEmpty(tree,active)){active=fields(tree)[0].id;render();focus();return;}let[a,b]=selection;if(a===b)a=Math.max(0,a-1);f.text=f.text.slice(0,a)+f.text.slice(b);render();focus(active,a);}else{const i=host.querySelector('.calc-linear');let a=i.selectionStart,b=i.selectionEnd;if(a===b)a=Math.max(0,a-1);text=text.slice(0,a)+text.slice(b);i.value=text;i.focus();i.setSelectionRange(a,a);}return;}
 if(['←','→','↑','↓'].includes(k)){if(mode==='natural'){const f=fields(tree).find(f=>f.id===active),p=selection[0];if(k==='←'&&p>0)focus(active,p-1);else if(k==='→'&&p<f.text.length)focus(active,p+1);else focus(navigate(tree,active,{'←':'left','→':'right','↑':'up','↓':'down'}[k]));}return;}
 if(k==='±'){if(mode==='natural'){const f=fields(tree).find(f=>f.id===active);f.text=f.text.startsWith('-(')&&f.text.endsWith(')')?f.text.slice(2,-1):f.text?'-('+f.text+')':'-';render();focus();}else{text=text.startsWith('-(')&&text.endsWith(')')?text.slice(2,-1):'-('+text+')';render();}return;}
 if(mode==='natural'){if(k==='a/b'){structure('Fraction');return;}if(k==='xʸ'||k==='x²'){structure('Power');if(k==='x²')add('2');return;}if(k==='√'||k==='ⁿ√'){structure(k==='√'?'Sqrt':'Root');return;}if(['sin','cos','tan','asin','acos','atan','log','ln','abs'].includes(k)){structure('Function',k);return;}if(k==='('){structure('Group');return;}if(k===')'){const next=exitStructure(tree,active);if(next!==active){focus(next,0);return;}}}
 const map={'a/b':'/','xʸ':'^','x²':'^2','√':'sqrt(','ⁿ√':'root(','1/x':'^(-1)','10ˣ':'10^(','eˣ':'exp(','×10ⁿ':'×10^('};add(map[k]??(['sin','cos','tan','asin','acos','atan','log','ln','abs'].includes(k)?k+'(':k));}
 function render(){host.replaceChildren();host.classList.add('three-calculator');host.onkeydown=e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();onClose();}};
 const bar=el('div','calc-modes');for(const [m,en,bm]of[['basic','Basic','Asas'],['scientific','Scientific','Saintifik'],['natural','Natural','Paparan Semula Jadi']]){const b=btn(tr(en,bm),()=>{if(m===mode)return;if(mode==='natural')text=serialize(tree);else if(m==='natural'){tree=sequence();fields(tree)[0].text=text;active=fields(tree)[0].id;}mode=m;remembered=m;try{sessionStorage.setItem('calculator-mode',m)}catch{}render();});b.setAttribute('aria-pressed',String(mode===m));bar.append(b);}bar.append(btn(tr('Close calculator','Tutup kalkulator'),onClose,'×'));host.append(bar);
 if(mode!=='basic'){const units=el('div','calc-units');for(const v of['DEG','RAD']){const b=btn(v,()=>{angle=v;render();});b.ariaLabel=v==='DEG'?tr('Degrees','Darjah'):tr('Radians','Radian');b.setAttribute('aria-pressed',String(v===angle));units.append(b);}host.append(units);}
 if(mode==='natural'){const editor=el('div','natural-editor');editor.setAttribute('role','group');editor.ariaLabel=tr('Natural expression','Ungkapan semula jadi');editor.append(treeDOM(tree));host.append(editor);}else{const input=el('input','calc-linear');input.value=text;input.ariaLabel=tr('Calculation','Pengiraan');input.autocomplete='off';input.spellcheck=false;input.oninput=()=>text=input.value;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();solve();}};host.append(input);}
 const out=el('output','calc-result');out.setAttribute('aria-live','polite');host.append(out);const toggle=btn(tr('Fraction or decimal','Pecahan atau perpuluhan'),()=>{exact=!exact;output()},'S⇔D');toggle.className='calc-exact';toggle.disabled=!result?.exact;host.append(toggle);
 const displayNames={asin:'sin⁻¹',acos:'cos⁻¹',atan:'tan⁻¹',C:'AC'};
 const makeKey=k=>{const b=btn(k,()=>key(k),displayNames[k]||k);if(k==='C'||k==='DEL')b.className='calc-clear';return b;};
 if(mode==='natural'){const nav=el('div','calc-navigation');['←','↑','↓','→'].forEach(k=>nav.append(makeKey(k)));host.append(nav);}
 const functions=el('div','calc-functions');const scientific=['a/b','√','ⁿ√','x²','xʸ','1/x','sin','cos','tan','asin','acos','atan','log','ln','10ˣ','eˣ','π','e','(',')','±','%','!','abs'];(mode==='basic'?['(',')','±','%']:scientific).forEach(k=>functions.append(makeKey(k)));host.append(functions);
 const keys=el('div','calc-keys');['7','8','9','DEL','C','4','5','6','×','÷','1','2','3','+','−','0','.',mode==='basic'?'%':'×10ⁿ','Ans','='].forEach(k=>keys.append(makeKey(k)));host.append(keys);output();}
 render();return{refresh:render,focus:()=>{if(mode==='natural')focus();else host.querySelector('.calc-linear').focus();}};
}
